// Personal annotations live only in this browser; original map records remain unchanged.
const MAP_NOTE_KEY='fw-map-notes-v1',MAP_NOTE_ICONS=['关卡','据点','道具','矿石','鱼','神殿'];
let mapNoteMode=false,mapNoteDraft=null,mapNotes=readMapNotes();
function normalizeMapNotes(rows){return Array.isArray(rows)?rows.filter(n=>n&&typeof n.id==='string'&&typeof n.title==='string'&&Number.isFinite(n.x)&&Number.isFinite(n.y)&&n.x>=0&&n.x<=100&&n.y>=0&&n.y<=100).slice(0,300).map(n=>({id:n.id.slice(0,80),title:n.title.slice(0,32),icon:MAP_NOTE_ICONS.includes(n.icon)?n.icon:'关卡',x:n.x,y:n.y,route:typeof n.route==='string'?n.route:(Object.entries(routes).find(([,label])=>n.group?.startsWith(label+'·'))?.[0]||'all'),group:typeof n.group==='string'?n.group.slice(0,24):'',items:Array.isArray(n.items)?n.items.filter(x=>typeof x==='string').slice(0,60).map(x=>x.slice(0,80)):[]})):[]}
function readMapNotes(){try{return normalizeMapNotes(JSON.parse(localStorage.getItem(MAP_NOTE_KEY)||'[]'))}catch{return []}}
function writeMapNotes(rows){try{localStorage.setItem(MAP_NOTE_KEY,JSON.stringify(rows));mapNotes=rows;return true}catch{toast('标记未能保存，请检查浏览器存储空间。');return false}}
function mapNoteEditor(){if(!mapNoteDraft)return '';const n=mapNoteDraft;return `<form class="map-note-editor" id="mapNoteEditor"><div class="map-note-editor-head"><b>${mapNotes.some(p=>p.id===n.id)?'编辑标记':'新建标记'}</b><button type="button" data-note-cancel aria-label="关闭标记编辑">×</button></div><label>所属地图<select name="route">${Object.entries({all:"全路线",...routes}).map(([r,label])=>`<option value="${r}" ${(n.route||"all")===r?"selected":""}>${label}</option>`).join("")}</select></label><label>标题<input name="title" maxlength="32" required value="${escapeAttr(n.title)}" placeholder="例如：下次来拿材料" autocomplete="off"></label>${n.items?.length?`<p class="map-note-targets">收集目标：${n.items.map(esc).join('、')}</p>`:''}<fieldset><legend>图标</legend><div class="map-note-icons">${MAP_NOTE_ICONS.map(icon=>`<label title="${icon}"><input type="radio" name="icon" value="${icon}" ${icon===n.icon?'checked':''}><span>${atlasIcon(icon)}</span><small>${icon}</small></label>`).join('')}</div></fieldset><div class="map-note-actions"><button type="submit" class="primary">保存标记</button><button type="button" data-note-cancel>取消</button>${mapNotes.some(p=>p.id===n.id)?'<button type="button" class="text-button" data-note-delete>删除标记</button>':''}</div></form>`}
function visibleMapNotes(){return mapNotes.filter(n=>mapArea==='all'||!n.route||n.route==='all'||n.route===mapArea)}
function mapNoteLabel(n){return n.group&&n.items?.length?n.items.join('、'):n.title}
function personalMapPins(){return visibleMapNotes().map(n=>`<button class="pin atlas-pin personal-map-pin" data-map-note="${escapeAttr(n.id)}" style="left:${n.x}%;top:${n.y}%" aria-label="我的标记：${escapeAttr(mapNoteLabel(n))}" title="${escapeAttr(mapNoteLabel(n))}">${atlasIcon(n.icon)}<span class="pin-label">${esc(mapNoteLabel(n))}</span></button>`).join('')}
function paintMapNotes(){const stage=document.querySelector('.atlas-stage');if(!stage)return;const canvas=stage.querySelector('.map-canvas');if(!canvas)return;let layer=stage.querySelector('.personal-map-pins');if(!layer){layer=document.createElement('div');layer.className='map-pins personal-map-pins';canvas.appendChild(layer)}layer.innerHTML=personalMapPins();stage.classList.toggle('map-note-mode',mapNoteMode);const toggle=stage.querySelector('[data-note-mode]');if(toggle){toggle.setAttribute('aria-pressed',String(mapNoteMode));toggle.textContent=mapNoteMode?'点地图放置标记 · 取消':'添加标记'}const host=stage.querySelector('#map-note-editor-host');if(host)host.innerHTML=mapNotePopover();positionMapNotePopover();const list=stage.querySelector('#personal-map-note-list');if(list)list.innerHTML=visibleMapNotes().map(n=>`<button type="button" data-map-note="${escapeAttr(n.id)}">${atlasIcon(n.icon)}<span>${esc(n.title)}</span></button>`).join('')||'<p class="muted">还没有标记。可标记任意位置，也可从地点详情保存。</p>';const count=stage.querySelector('[data-note-count]');if(count)count.textContent=visibleMapNotes().length;}
const mapNotesBasePage=mapPage;
mapPage=function(){let html=mapNotesBasePage();if(!mapLoaded)return html;html=html.replace('<div class="map-viewport"','<div class="map-annotation-tools"><section class="personal-map-notes"><div class="personal-map-notes-head"><details class="map-note-library"><summary>我的标记 <small data-note-count>'+mapNotes.length+'</small></summary><div id="personal-map-note-list"></div></details><button type="button" data-note-mode aria-pressed="'+mapNoteMode+'">添加标记</button></div></section></div><div class="map-viewport"');return html.replace('<div class="map-viewport"','<div id="map-note-editor-host"></div><div class="map-viewport"')};
function mapNotePopover(){if(mapNoteDraft)return mapNoteEditor();const p=typeof mapSelected==='undefined'?null:PINS.find(p=>p.id===mapSelected);if(!p)return '';const existing=visibleMapNotes().some(n=>Math.abs(n.x-p.x)<.0001&&Math.abs(n.y-p.y)<.0001);const area=typeof routes!=='undefined'&&routes[p.area]||p.area||'',detail=typeof mapPinDetail==='function'?mapPinDetail(p.id):'';const html=`<div class="map-point-popover"><div class="map-popover-title"><b>${esc(p.name)}</b><small>${esc([area,p.type].filter(Boolean).join(' · '))}</small></div><button type="button" class="text-button" data-note-place="${escapeAttr(p.id)}">${existing?'编辑标记':'存为标记'}</button><button type="button" data-map-pin-close aria-label="关闭地点操作">×</button>${detail?`<div class="map-popover-brief">${detail}</div>`:''}</div>`;return typeof zhHTML==='function'?zhHTML(html):html}
function positionMapNotePopover(){
 const host=document.querySelector('#map-note-editor-host'),view=document.querySelector('.atlas-stage .map-viewport'),canvas=view?.querySelector('.map-canvas');if(!host||!view||!canvas||!host.firstElementChild)return;
 const point=mapNoteDraft||(typeof mapSelected!=='undefined'?PINS.find(p=>p.id===mapSelected):null);if(!point){host.hidden=true;return}
 const raw=view.getBoundingClientRect(),vr={left:raw.left,right:raw.right,width:raw.width,top:Math.max(raw.top,0),bottom:Math.min(raw.bottom,window.innerHeight)},cr=canvas.getBoundingClientRect(),parent=host.parentElement.getBoundingClientRect(),x=cr.left+cr.width*point.x/100,y=cr.top+cr.height*point.y/100;
 host.hidden=x<vr.left||x>vr.right||y<vr.top||y>vr.bottom;if(host.hidden)return;
 host.style.width=Math.min(mapNoteDraft?320:310,vr.width-16)+'px';const h=host.offsetHeight,w=host.offsetWidth;
 const left=Math.max(vr.left+8,Math.min(vr.right-w-8,x-w/2)),above=y-h-28,top=above>=vr.top+8?above:Math.max(vr.top+8,Math.min(vr.bottom-h-8,y+24));
 host.style.left=(left-parent.left)+'px';host.style.top=(top-parent.top)+'px';host.style.setProperty('--note-arrow-x',Math.max(14,Math.min(w-14,x-left))+'px');host.classList.toggle('below-point',above<vr.top+8);
}
function focusMapNote(n){const v=document.querySelector('.atlas-stage .map-viewport');if(!v)return;mapScale=Math.max(mapScale,2.4);const scale=mapBase*mapScale;mapX=v.clientWidth/2-n.x/100*3328*scale;mapY=v.clientHeight*.72-n.y/100*2560*scale;clampMap();scheduleMap()}
function newMapNote(x,y,title=''){mapNoteMode=false;mapNoteDraft={id:'note-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),title,icon:'关卡',x,y,route:mapArea};paintMapNotes();document.querySelector('#mapNoteEditor input[name="title"]')?.focus({preventScroll:true})}
function mapNotePoint(clientX,clientY,rect){return {x:Math.max(0,Math.min(100,(clientX-rect.left)/rect.width*100)),y:Math.max(0,Math.min(100,(clientY-rect.top)/rect.height*100))}}
function closeMapNoteEditor(){mapNoteDraft=null;mapNoteMode=false;paintMapNotes()}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-note-mode],[data-note-cancel],[data-note-delete],[data-map-note],[data-note-place]');if(b){e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-note-mode')){mapNoteMode=!mapNoteMode;mapNoteDraft=null;paintMapNotes();document.querySelector('.map-main')?.scrollIntoView({block:'nearest',behavior:'smooth'})}else if(b.hasAttribute('data-note-cancel'))closeMapNoteEditor();else if(b.hasAttribute('data-note-delete')){if(writeMapNotes(mapNotes.filter(n=>n.id!==mapNoteDraft?.id)))closeMapNoteEditor()}else if(b.hasAttribute('data-note-place')){const p=PINS.find(p=>p.id===b.dataset.notePlace);if(p){const existing=visibleMapNotes().find(n=>Math.abs(n.x-p.x)<.0001&&Math.abs(n.y-p.y)<.0001);if(existing){mapNoteDraft={...existing};paintMapNotes();positionMapNotePopover()}else newMapNote(p.x,p.y,p.name)}}else{const n=mapNotes.find(n=>n.id===b.dataset.mapNote);if(n){mapNoteMode=false;mapNoteDraft={...n};if(!b.classList.contains("pin"))focusMapNote(mapNoteDraft);paintMapNotes();document.querySelector('#mapNoteEditor input')?.focus({preventScroll:true})}}return;}if(e.target.closest?.('[data-pin],[data-map-pin-close]')){mapNoteDraft=null;mapNoteMode=false;requestAnimationFrame(paintMapNotes);return;}if(!mapNoteMode||performance.now()<mapDragUntil||!e.target.closest?.('.atlas-stage .map-viewport')||e.target.closest('.pin'))return;const rect=document.querySelector('.atlas-stage .map-canvas')?.getBoundingClientRect();if(rect?.width&&rect?.height){const p=mapNotePoint(e.clientX,e.clientY,rect);newMapNote(p.x,p.y)}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='mapNoteEditor')return;e.preventDefault();const form=e.target,title=form.elements.title.value.trim();if(!title){form.elements.title.setCustomValidity('请填写标记标题');form.elements.title.reportValidity();return}const icon=form.elements.icon.value,n={...mapNoteDraft,route:form.elements.route?.value||mapNoteDraft.route||'all',title:title.slice(0,32),icon:MAP_NOTE_ICONS.includes(icon)?icon:'关卡'};if(writeMapNotes([...mapNotes.filter(p=>p.id!==n.id),n])){closeMapNoteEditor();toast('标记已保存在当前浏览器')}});
document.addEventListener('input',e=>{if(e.target.closest?.('#mapNoteEditor')&&e.target.name==='title'){e.target.setCustomValidity('');if(mapNoteDraft)mapNoteDraft.title=e.target.value}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(mapNoteDraft||mapNoteMode))closeMapNoteEditor()});
const mapNotesBaseRender=render;render=function(){const out=mapNotesBaseRender();if(typeof document.querySelector==='function')paintMapNotes();return out};
window.addEventListener('storage',e=>{if(e.key===MAP_NOTE_KEY){mapNotes=readMapNotes();paintMapNotes()}});
if(DB)paintMapNotes();

window.addEventListener('resize',positionMapNotePopover);
